// ATOM2_07 · Motivos de perda (03_FUNIS_PIPEDRIVE.md §5). Idempotente: só acrescenta o que falta.
const API = 'https://api.pipedrive.com/v1';
const MOTIVOS = ['Sem resposta', 'Agora não (sem recontato)', 'Agora não (recontato autorizado)', 'Investimento', 'Já tem fornecedor', 'Não compareceu', 'Fora do perfil', 'Sem interesse', 'Opt-out (não contatar)', 'Duplicado', 'Contato inválido', 'Não é cliente (emprego/fornecedor)', 'Paciente buscando atendimento clínico'];
const campos = ($('Ler campos').first().json.data) || [];
const igual = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
const out = [];
const nativo = campos.find((c) => c.key === 'lost_reason');
if (nativo) {
  const atuais = (nativo.options || []).map((o) => ({ id: o.id, label: o.label }));
  const faltam = MOTIVOS.filter((m) => !atuais.some((o) => igual(o.label, m)));
  out.push(faltam.length ? { method: 'PUT', url: API + '/dealFields/' + nativo.id, body: { options: [...atuais, ...faltam.map((label) => ({ label }))] }, ref: 'nativo' } : { method: 'GET', url: API + '/users/me', body: {}, ref: 'nativo:ok' });
}
const proprio = campos.find((c) => igual(c.name, 'ATOM · Motivo de perda'));
if (!proprio) out.push({ method: 'POST', url: API + '/dealFields', body: { name: 'ATOM · Motivo de perda', field_type: 'enum', options: MOTIVOS.map((label) => ({ label })) }, ref: 'proprio' });
else {
  const faltam = MOTIVOS.filter((m) => !(proprio.options || []).some((o) => igual(o.label, m)));
  out.push(faltam.length ? { method: 'PUT', url: API + '/dealFields/' + proprio.id, body: { options: [...(proprio.options || []).map((o) => ({ id: o.id, label: o.label })), ...faltam.map((label) => ({ label }))] }, ref: 'proprio' } : { method: 'GET', url: API + '/users/me', body: {}, ref: 'proprio:ok' });
}
return out.map((j) => ({ json: j }));

// Grava chaves dos motivos em atom2_config e o resultado de cada tentativa (o campo nativo pode recusar edição pela API).
const campos = ($('Reler campos').first().json.data) || [];
const res = $('Aplicar').all().map((i, n) => ({ ref: $('Plano').all()[n].json.ref, status: i.json.statusCode, ok: i.json.body && i.json.body.success === true, erro: i.json.body && (i.json.body.error || i.json.body.error_info) || null }));
const nat = campos.find((c) => c.key === 'lost_reason');
const prop = campos.find((c) => String(c.name).trim() === 'ATOM · Motivo de perda');
const slug = (s) => String(s).normalize('NFD').replace(/\p{M}/gu, '').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_|_$/g, '');
const out = [{ chave: 'PD2_MOTIVOS_RESULTADO', valor: JSON.stringify(res).slice(0, 900), status: 'CONFIGURADO', descricao: 'Resultado do setup de motivos de perda (nativo e próprio)' }];
if (prop) {
  out.push({ chave: 'PD2_FIELD_MOTIVO_PERDA', valor: prop.key, status: 'CONFIGURADO', descricao: 'Chave do campo ATOM · Motivo de perda' });
  for (const o of prop.options || []) out.push({ chave: 'PD2_OPT_MOTIVO_' + slug(o.label), valor: String(o.id), status: 'CONFIGURADO', descricao: 'Motivo de perda: ' + o.label });
}
out.push({ chave: 'PD2_LOST_REASON_NATIVO', valor: nat && (nat.options || []).length ? 'SIM' : 'NAO', status: 'CONFIGURADO', descricao: 'SIM se a lista nativa de motivos do Pipedrive foi preenchida; NAO = usar texto livre + campo próprio' });
return out.map((j) => ({ json: j }));
